function updateSensorTiming(delta){const source={lidar:'lidar',imu:'imu',odom:'esc_odom'};for(const ch of ['lidar','imu','odom']){const sample=delta?.[source[ch]];if(!sample||typeof sample!=='object')continue;const stamp=+sample.measurement_stamp_sec;if(!Number.isFinite(stamp))continue;const r=sensorTiming.get(ch)||{last:null,dt:[]};if(Number.isFinite(r.last)&&stamp>r.last){const dt=stamp-r.last;if(dt>0.001&&dt<5){r.dt.push(dt);while(r.dt.length>80)r.dt.shift()}}r.last=stamp;sensorTiming.set(ch,r)}}
function timingMetric(ch,kind){const r=sensorTiming.get(ch);if(!r||!r.dt.length)return undefined;const mean=r.dt.reduce((a,b)=>a+b,0)/r.dt.length;if(kind==='rate')return mean>0?1/mean:undefined;const variance=r.dt.reduce((a,b)=>a+(b-mean)*(b-mean),0)/r.dt.length;return Math.sqrt(Math.max(0,variance))*1000}
