function connectSse(){if(sse)sse.close();sse=new EventSource('/api/events');sse.onopen=()=>{setText('sseLabel','Live stream');$('sseDot').style.background='var(--green)';setText('diagSse','CONNECTED');setText('footerStatus','ROS2 realtime telemetry connected')};sse.addEventListener('snapshot',e=>{try{merge(JSON.parse(e.data))}catch(_){}});sse.onmessage=e=>{try{merge(JSON.parse(e.data))}catch(_){}};sse.onerror=()=>{setText('sseLabel','Reconnecting');$('sseDot').style.background='var(--amber)';setText('diagSse','RETRYING');setText('footerStatus','Reconnecting realtime telemetry…')}}
function anyChannelFresh(keys,sec){return keys.some(k=>channelFresh(k,sec))}
// HMI sensor state follows the same principle as Local GUI System Overview:
// fresh measured telemetry is the source of truth. connected.* is supplemental
// diagnostics only and may not force a live sensor OFFLINE.
function telemetryHealth(keys,freshSec=2,offlineSec=3.5){const a=Array.isArray(keys)?keys:[keys];if(anyChannelFresh(a,freshSec))return'ok';if(anyChannelFresh(a,offlineSec))return'warn';return'bad'}
function sensorHealth(name){
  if(name==='lidar')return telemetryHealth(['lidar'],2.0,3.5);
  if(name==='imu')return telemetryHealth(['imu'],2.0,3.5);
  if(name==='camera'){
    const h=telemetryHealth(['camera_frame','camera_status'],3.5,8.0);
    if(h==='bad')return'bad';
    if(channelFresh('camera_healthy',8)&&raw('camera_healthy')===false)return'warn';
    return h;
  }
  if(name==='esc'){
    const h=telemetryHealth(['esc_status','esc_odom'],2.0,3.5);
    if(h==='bad')return'bad';
    return (bool(raw('connected.esc_feedback'))||bool(raw('connected.esc_ready')))?h:'warn';
  }
  if(name==='winch'){
    const h=telemetryHealth(['winch.state','winch.raw','winch.pwm_pct','winch.servo_deg'],2.0,4.0);
    if(h!=='bad')return h;
    return bool(raw('connected.winch'))&&channelFresh('connected.winch',4)?'warn':'bad';
  }
  return'bad';
}
function sensorAvailable(name){return sensorHealth(name)!=='bad'}
function sensorOnline(name){return sensorHealth(name)==='ok'}
function healthFromConnected(key){const map={'connected.lidar':'lidar','connected.imu':'imu','connected.camera':'camera','connected.winch':'winch'};return map[key]?sensorHealth(map[key]):(bool(raw(key))&&channelFresh(key,5)?'ok':channelFresh(key,8)?'warn':'bad')}
function renderOverview(){const li=sensorHealth('lidar'),im=sensorHealth('imu'),ca=sensorHealth('camera'),es=sensorHealth('esc'),wi=sensorHealth('winch');const motion=bool(raw('system.motion_ready'))||bool(raw('system.autonomy_motion_allowed'));const amclLocked=localizationLocked(),amclFresh=channelFresh('amcl',4),loc=(amclLocked||amclFresh)?'ok':(channelFresh('ekf_local',4)?'warn':'bad');const nv=bool(raw('system.nav2_ready'))?'ok':(channelFresh('nav2_runtime',5)?'warn':'bad');const ld=obj('lidar');healthCard('lidar',li,Number.isFinite(+ld.scan_rate_hz)?fmt(ld.scan_rate_hz,1)+' Hz / '+fmt(ld.valid_ratio_pct,1)+'% valid':'waiting /scan_nav');healthCard('imu',im,channelFresh('imu',3)?'data /imu/data fresh':'waiting /imu/data');healthCard('camera',ca,obj('camera_frame').source||'Astra Pro');healthCard('esc',es,es==='ok'?'ESC telemetry + ACK fresh':es==='warn'?'ESC telemetry fresh • ACK/ready pending':'waiting ESC telemetry');const ws=raw('winch.state'),wp=raw('winch.port');healthCard('winch',wi,wi!=='bad'?`${textish(ws)||'CONNECTED'} • ${textish(wp)||'STM32 CDC'}`:'waiting STM32 CDC telemetry');healthCard('localization',loc,amclLocked?(amclFresh?'AMCL localized • pose fresh':'AMCL localized • robot stationary'):amclFresh?'AMCL pose fresh':'waiting localization');healthCard('nav2',nv,bool(raw('system.nav2_ready'))?'planner/controller/BT present':'waiting Nav2 runtime');const states=[li,im,ca,es,loc,nv],score=Math.round(states.reduce((a,x)=>a+(x==='ok'?1:x==='warn'?.5:0),0)/states.length*100);$('readinessRing').style.setProperty('--pct',score);setText('readinessPct',score+'%');setText('readinessTitle',motion?'Vehicle motion-ready':score>=70?'Core runtime online, safety gates pending':'System commissioning / offline');setText('readinessDetail',motion?'Localization, Nav2 and actuator safety gates report ready.':'Periksa LiDAR, IMU, AMCL, Nav2, perception, dan ESC. Motion tetap fail-closed sampai gate aktual siap.');setText('overallChip',motion?'MOTION READY':'FAIL-CLOSED');$('overallChip').className='status-chip '+(motion?'':'waiting');const pose=localizationPose(),imu=obj('imu');setText('overviewSpeed',fmt(getPath(obj('esc_odom'),'v')??getPath(obj('ekf_local'),'v')));setText('overviewSteer',fmt(deg(raw('esc_steer_actual')),1));setText('overviewYaw',fmt(deg(getPath(pose,'yaw')??getPath(imu,'yaw_rad')),1));setText('goalStateBig',getPath(obj('goal_state'),'state')||'IDLE');setText('activeSourceBig','ACTUATOR: '+(getPath(obj('esc_mux'),'raw')||'--'));setText('lastUpdate',new Date().toLocaleTimeString('id-ID'));const cn=obj('cmd_nav'),cs=obj('cmd_autonomy_integrated'),cf=obj('cmd_final'),caa=obj('cmd_actuator');setText('pipeNav',fmt(cn.linear_x));setText('pipeSafety',fmt(cs.linear_x));setText('pipeFinal',fmt(cf.linear_x));setText('pipeActuator',fmt(caa.linear_x));history.push({t:Date.now(),nav:+cn.linear_x||0,final:+cf.linear_x||0,actual:+raw('esc_drive_actual')||0});while(history.length>180)history.shift();drawSpark();renderAlerts();}
function renderAlerts(){const a=[];if(bool(raw('system.estop')))a.push(['danger','Emergency stop ACTIVE']);if(bool(raw('perception_emergency')))a.push(['danger','Perception emergency stop ACTIVE']);if(!bool(raw('connected.esc_feedback')))a.push(['danger','ESC ACK belum fresh - motor command tidak dianggap ready']);if(sensorHealth('lidar')==='bad')a.push(['warn','LiDAR /scan_nav belum fresh']);if(sensorHealth('imu')==='bad')a.push(['warn','IMU /imu/data belum fresh']);if(!localizationLocked()&&!channelFresh('amcl',4))a.push(['warn','AMCL localization belum valid']);if(!(bool(raw('system.motion_ready'))||bool(raw('system.autonomy_motion_allowed'))))a.push(['warn','Motion gate masih tertutup']);if((bool(raw('system.motion_ready'))||bool(raw('system.autonomy_motion_allowed')))&&bool(raw('connected.esc_feedback')))a.push(['ok','Core motion chain ready']);setText('alertCount',a.filter(x=>x[0]!=='ok').length);$('alerts').innerHTML=a.length?a.map(x=>'<div class="alert-item '+x[0]+'">'+escapeHtml(x[1])+'</div>').join(''):'<div class="empty-state">Tidak ada kondisi aktif.</div>';}
function drawSpark(){const c=$('speedSpark'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const css=getComputedStyle(document.body);ctx.strokeStyle=css.getPropertyValue('--border2');ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();if(history.length<2)return;const max=Math.max(1,...history.flatMap(x=>[Math.abs(x.nav),Math.abs(x.final),Math.abs(x.actual)]));[['nav','--blue'],['final','--green'],['actual','--cyan']].forEach(([key,col])=>{ctx.strokeStyle=css.getPropertyValue(col);ctx.lineWidth=2;ctx.beginPath();history.forEach((p,i)=>{const x=i/(history.length-1)*w,y=h/2-(p[key]/max)*(h*.38);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
