  poseCanvas.addEventListener('pointermove',e=>{if(!poseEstimateMode||!poseEstimateDrag||poseEstimateDrag.pointerId!==e.pointerId)return;const p=mapPointerWorld(e);if(p)poseEstimateDrag.current=p;e.preventDefault();drawMap()});
  poseCanvas.addEventListener('pointerup',async e=>{if(!poseEstimateMode||!poseEstimateDrag||poseEstimateDrag.pointerId!==e.pointerId)return;const end=mapPointerWorld(e)||poseEstimateDrag.current,start=poseEstimateDrag.start;try{poseCanvas.releasePointerCapture(e.pointerId)}catch(_e){}poseEstimateDrag.current=end;const dx=end.x-start.x,dy=end.y-start.y,dist=Math.hypot(dx,dy);if(dist<Math.max(0.08,start.resolution*2)){toast('Arah belum terbentuk. Drag sedikit lebih jauh untuk menentukan yaw robot.',true);poseEstimateDrag=null;drawMap();return}const yaw=Math.atan2(dy,dx);const payload={x:start.x,y:start.y,yaw_rad:yaw};poseEstimateDrag=null;setPoseEstimateMode(false);const r=await post('/api/localization/initial-pose',payload);if(r?.ok)toast(`Initial pose dikirim: X=${start.x.toFixed(2)} m, Y=${start.y.toFixed(2)} m, yaw=${(yaw*180/Math.PI).toFixed(1)}°`);else toast(r?.message||'Gagal mengirim /initialpose',true);e.preventDefault()});
