function alignmentCanvasToRaw(p,rawW,rawH){
  if(!Array.isArray(p)||!Number.isFinite(+p[0])||!Number.isFinite(+p[1])||!Number.isFinite(+rawW)||!Number.isFinite(+rawH)||rawW<=0||rawH<=0)return null;
  const procW=+(configValue('alignment','video.processing_width')??1280),procH=+(configValue('alignment','video.processing_height')??720);
  const lbScale=Math.min(procW/rawW,procH/rawH);if(!Number.isFinite(lbScale)||lbScale<=0)return null;
  const padX=(procW-rawW*lbScale)*.5,padY=(procH-rawH*lbScale)*.5;
  return [((+p[0])-padX)/lbScale,((+p[1])-padY)/lbScale];
}
function drawYoloDetections(ctx,pt,dpr){
  const d=obj('raw_detections'),df=channelFresh('raw_detections',2),p=obj('warehouse_person_detections'),pf=channelFresh('warehouse_person_detections',2.5);
  const primary=df&&Array.isArray(d.items)?d.items:[],persons=pf&&Array.isArray(p.items)?p.items.map(x=>({...x,_personSemantic:true})):[],items=[...primary,...persons];
  ctx.font=`${10*dpr}px ui-monospace`;ctx.textBaseline='top';
  for(const o of items.slice(0,40)){
    if(!Number.isFinite(+o.x1)||!Number.isFinite(+o.y1)||!Number.isFinite(+o.x2)||!Number.isFinite(+o.y2))continue;
    const p1=pt([o.x1,o.y1]),p2=pt([o.x2,o.y2]);if(!p1||!p2)continue;
    const color=o._personSemantic?'#ff7a45':o.in_danger_zone?'#ff334d':o.on_path?'#ffc84d':'#48d9ff';
    ctx.strokeStyle=color;ctx.lineWidth=Math.max(1.5,1.5*dpr);ctx.strokeRect(p1[0],p1[1],p2[0]-p1[0],p2[1]-p1[1]);
    const name=o._personSemantic?'PERSON • DYNAMIC':String(o.class_name||o.category||`ID ${o.class_id??'?'}`),conf=Number.isFinite(+o.confidence)?` ${(100*(+o.confidence)).toFixed(0)}%`:'';
    const txt=name+conf,w=ctx.measureText(txt).width+8*dpr,h=15*dpr;ctx.fillStyle='rgba(0,0,0,.68)';ctx.fillRect(p1[0],Math.max(0,p1[1]-h),w,h);ctx.fillStyle=color;ctx.fillText(txt,p1[0]+4*dpr,Math.max(0,p1[1]-h)+2*dpr);
  }
}
function drawAlignmentOverlay(a=latestAlignment){
  const c=$('alignmentOverlayCanvas'),img=$('cameraImage');
  if(!c)return;
  const rect=c.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);
  const cw=Math.max(1,Math.round(rect.width*dpr)),ch=Math.max(1,Math.round(rect.height*dpr));
  if(c.width!==cw||c.height!==ch){c.width=cw;c.height=ch}
  const ctx=c.getContext('2d');ctx.clearRect(0,0,cw,ch);
  const fresh=a&&a.available===true&&Number.isFinite(+a.at_ms)&&(Date.now()-a.at_ms)<1800;
  const sw=(img&&img.naturalWidth)||1280,sh=(img&&img.naturalHeight)||720;
  if(sw<=0||sh<=0)return;
  const scale=Math.min(cw/sw,ch/sh),ox=(cw-sw*scale)/2,oy=(ch-sh*scale)/2;
  const pt=p=>Array.isArray(p)&&Number.isFinite(+p[0])&&Number.isFinite(+p[1])?[ox+(+p[0])*scale,oy+(+p[1])*scale]:null;
  const apt=p=>{const raw=alignmentCanvasToRaw(p,sw,sh);return raw?pt(raw):null};
  drawYoloDetections(ctx,pt,dpr);
  if(!fresh)return;
  const circle=(p,r,color)=>{if(!p)return;ctx.strokeStyle=color;ctx.lineWidth=Math.max(2,2*dpr);ctx.beginPath();ctx.arc(p[0],p[1],r*dpr,0,Math.PI*2);ctx.stroke()};
  const line=(p1,p2,color,width=2)=>{if(!p1||!p2)return;ctx.strokeStyle=color;ctx.lineWidth=Math.max(1,width*dpr);ctx.beginPath();ctx.moveTo(p1[0],p1[1]);ctx.lineTo(p2[0],p2[1]);ctx.stroke()};
  const cross=(p,r,color)=>{if(!p)return;line([p[0]-r*dpr,p[1]],[p[0]+r*dpr,p[1]],color,2);line([p[0],p[1]-r*dpr],[p[0],p[1]+r*dpr],color,2)};
  const sb=a.setpoint_box,sc=apt(a.setpoint_center);
  if(Array.isArray(sb)&&sb.length===4&&sb.every(v=>Number.isFinite(+v))){
    const p1=apt([sb[0],sb[2]]),p2=apt([sb[1],sb[3]]);
    ctx.strokeStyle='#ff334d';ctx.lineWidth=Math.max(2,2*dpr);
    ctx.strokeRect(p1[0],p1[1],p2[0]-p1[0],p2[1]-p1[1]);
    cross(sc,9,'#ff334d');
  }
  const lh=apt(a.left_hole_center),rh=apt(a.right_hole_center);
  if(a.left_hole_valid&&a.right_hole_valid&&lh&&rh){
    line(lh,rh,'#ffd84d',2);circle(lh,7,'#ffd84d');circle(rh,7,'#ffd84d');
    const mid=apt(a.holes_midpoint);if(mid){ctx.fillStyle='#ffd84d';ctx.beginPath();ctx.moveTo(mid[0],mid[1]-6*dpr);ctx.lineTo(mid[0]+6*dpr,mid[1]);ctx.lineTo(mid[0],mid[1]+6*dpr);ctx.lineTo(mid[0]-6*dpr,mid[1]);ctx.closePath();ctx.strokeStyle='#ffd84d';ctx.lineWidth=2*dpr;ctx.stroke()}
  }
  const bc=apt(a.detected_block_center),bb=a.detected_block_box;
  if(a.block_detected&&bc){
    if(Array.isArray(bb)&&bb.length===4&&bb.every(v=>Number.isFinite(+v))){
      const p1=apt([bb[0],bb[1]]),p2=apt([bb[2],bb[3]]);
      ctx.strokeStyle='#35e69f';ctx.lineWidth=Math.max(2,2*dpr);ctx.strokeRect(p1[0],p1[1],p2[0]-p1[0],p2[1]-p1[1]);
    }
    circle(bc,6,'#35e69f');
    if(sc){
      line(bc,sc,'#ff30ef',2);
      const ang=Math.atan2(sc[1]-bc[1],sc[0]-bc[0]),r=10*dpr;
      const pA=[sc[0]-r*Math.cos(ang-.55),sc[1]-r*Math.sin(ang-.55)];
      const pB=[sc[0]-r*Math.cos(ang+.55),sc[1]-r*Math.sin(ang+.55)];
      line(sc,pA,'#ff30ef',2);line(sc,pB,'#ff30ef',2);
    }
  }
}
