  if(calPixelMeasure.a&&calPixelMeasure.b){const A=calPixelMeasure.a,B=calPixelMeasure.b;ctx.strokeStyle='#fff';ctx.lineWidth=2*dpr;ctx.setLineDash([6*dpr,4*dpr]);ctx.beginPath();ctx.moveTo(X(A.x),Y(A.y));ctx.lineTo(X(B.x),Y(B.y));ctx.stroke();ctx.setLineDash([])}
  if(calPixelMeasure.hover){const h=calPixelMeasure.hover;ctx.strokeStyle='rgba(255,255,255,.28)';ctx.lineWidth=dpr;ctx.beginPath();ctx.moveTo(X(h.x),oy);ctx.lineTo(X(h.x),oy+nh*scale);ctx.moveTo(ox,Y(h.y));ctx.lineTo(ox+nw*scale,Y(h.y));ctx.stroke()}
  ctx.restore();
  const A=calPixelMeasure.a,B=calPixelMeasure.b,H=calPixelMeasure.hover,dx=A&&B?B.x-A.x:NaN,dy=A&&B?B.y-A.y:NaN,dist=Number.isFinite(dx)&&Number.isFinite(dy)?Math.hypot(dx,dy):NaN;
  setText('calPixelCursor',H?`X ${H.x.toFixed(1)} • Y ${H.y.toFixed(1)} px`:'--');setText('calPixelPointA',A?`X ${A.x.toFixed(1)} • Y ${A.y.toFixed(1)}`:'--');setText('calPixelPointB',B?`X ${B.x.toFixed(1)} • Y ${B.y.toFixed(1)}`:'--');setText('calPixelDx',Number.isFinite(dx)?`${dx>=0?'+':''}${dx.toFixed(2)} px`:'--');setText('calPixelDy',Number.isFinite(dy)?`${dy>=0?'+':''}${dy.toFixed(2)} px`:'--');setText('calPixelDistance',Number.isFinite(dist)?`${dist.toFixed(2)} px`:'--');
