function syncLoopClosureSession(){const ms=obj('mapping_status'),slot=Number(ms.slot||0),active=ms.active===true&&slot>=1&&slot<=3;if(active&&!loopClosureSession.active)startLoopClosureSession(slot);if(active&&Number(loopClosureSession.slot)!==slot)startLoopClosureSession(slot);if(active&&loopClosureSession.active){loopClosureSession.structure=(ms.structure_metrics&&typeof ms.structure_metrics==='object')?{...ms.structure_metrics}:{};const pose=loopPoseFromMapping();if(!pose){loopClosureSession.status='WAITING_POSE';return}if(!loopClosureSession.reference){loopClosureSession.reference={...pose};loopClosureSession.referenceAt=Date.now();loopClosureSession.status='CAPTURING'}const ref=loopClosureSession.reference,dx=pose.x-ref.x,dy=pose.y-ref.y,dyaw=wrapPi(pose.yaw-ref.yaw),now=Date.now(),sec=Math.max(0,Math.floor((now-loopClosureSession.referenceAt)/1000));loopClosureSession.current={...pose,loop_error_m:Math.hypot(dx,dy),loop_yaw_error_deg:Math.abs(dyaw)*180/Math.PI};loopClosureSession.status='CAPTURING';if(sec!==loopClosureSession.lastSampleSec){loopClosureSession.lastSampleSec=sec;loopClosureSession.samples.push({t:now,s:sec,loop_error_m:loopClosureSession.current.loop_error_m,loop_yaw_error_deg:loopClosureSession.current.loop_yaw_error_deg});while(loopClosureSession.samples.length>1800)loopClosureSession.samples.shift()}mirrorLoopClosureHistory()}else if(!active&&loopClosureSession.active&&!loopClosureStopPending){const saved=Number(ms.saved_slot||0)===Number(loopClosureSession.slot);finalizeLoopClosureSession(saved?'SAVED':'STOPPED')}}
