async function loadPerceptionTrainingResults(force=false){if(perceptionTrainingLoading)return perceptionTraining;if(perceptionTraining&&!force)return perceptionTraining;perceptionTrainingLoading=true;try{const r=await fetch('/perception_training_results.json'+(force?'?t='+Date.now():''),{cache:force?'no-store':'default'});if(!r.ok)throw new Error('HTTP '+r.status);perceptionTraining=await r.json()}catch(e){perceptionTraining={rows:[],error:e.message}}finally{perceptionTrainingLoading=false}if(currentExp==='perception'&&selectedExperiment?.id==='4.1.5'){renderExperimentTable();renderExperimentGraphs();renderSourceAudit()}return perceptionTraining}
async function loadExperiments(){try{experiments=await (await fetch('/api/experiments',{cache:'no-store'})).json();normalizeNavigationCatalogToReport();normalizePerceptionCatalogToReport();loadPerceptionTrainingResults();setText('labLeafCount',Object.values(experiments).reduce((n,a)=>n+(a?.length||0),0));setText('navTestCount',(experiments.navigation||[]).length);setText('perTestCount',(experiments.perception||[]).length);setText('escTestCount',(experiments.steering||[]).length);renderExperimentList();const list=effectiveExperimentList();if(list.length)selectExperimentById(list[0].id)}catch(e){$('experimentList').innerHTML='<div class="empty-state">Catalog unavailable: '+escapeHtml(e.message)+'</div>'}}
function renderExperimentList(){const term=($('experimentSearch')?.value||'').trim().toLowerCase();const list=effectiveExperimentList().filter(x=>!term||`${x.id} ${x.section} ${x.groupTitle}`.toLowerCase().includes(term));const visited=visitedSet();let lastGroup='',html='';for(const x of list){const group=x.id.startsWith('F')?'FINAL THESIS DATASET':x.groupTitle||x.groupId||'BAB IV';if(group!==lastGroup){html+=`<div class="chapter-group"><span>${escapeHtml(group)}</span></div>`;lastGroup=group}html+=`<button class="experiment-item ${selectedExperiment?.id===x.id?'active':''}" data-id="${escapeHtml(x.id)}"><i>${visited.has(x.id)?'✓':'○'}</i><div><span>${escapeHtml(x.id)}</span><b>${escapeHtml(x.section||x.id)}</b><small>${(x.tableNames||[]).length} tabel • ${(x.graphCaptions||[]).length} grafik • ${tuningFieldsFor(x).filter(p=>p.yamlFileKey).length} parameter</small></div></button>`} $('experimentList').innerHTML=html||'<div class="empty-state">Tidak ada subbab yang cocok.</div>';qa('.experiment-item',$('experimentList')).forEach(e=>e.onclick=()=>selectExperimentById(e.dataset.id));setText('chapterDomainTitle',currentExp==='navigation'?'Navigasi':currentExp==='perception'?'Persepsi':'ESC / FOC');renderChapterProgress()}
function selectExperimentById(id){const x=(experiments[currentExp]||[]).find(v=>v.id===id);if(!x)return;selectedExperiment=x;selectedTableIndex=0;selectedGraphIndex=0;metricHistory.clear();scatterHistory.clear();tableRunRows.clear();trajectoryHistory.length=0;trajectoryPlanHistory.length=0;chartEpochMs=Date.now();lastLabSecond=-1;if(currentExp==='navigation'&&id==='4.2.4')mirrorLoopClosureHistory();configureExperimentRate();markVisited(id);renderExperimentList();renderSelectedExperiment();captureLabTelemetry();refreshExperimentLivePanels(true)}
function renderSelectedExperiment(){const x=selectedExperiment;if(!x)return;if(currentExp==='navigation'&&x.id==='4.2.5')restoreBab425GroundTruth();setText('experimentGroup',x.groupTitle||x.groupId||currentExp.toUpperCase());setText('experimentTitle',x.section||x.id);setText('experimentSubtitle',`${currentExp==='navigation'?'Navigasi':currentExp==='perception'?'Persepsi':'ESC / FOC'} • source catalog ${x.id} • data aktual ROS, tanpa dummy.`);setText('experimentTableBadge',`${(x.tableNames||[]).length} TABLE`);setText('experimentGraphBadge',`${(x.graphCaptions||[]).length} GRAPH`);setText('experimentRawMetadata',JSON.stringify(x,null,2));renderTuningFields();renderLabTabs();renderExperimentGraphs();renderExperimentTable();renderContextVisual();renderSourceAudit();updateRunControlMode()}
function tuningValueEqual(a,b){return JSON.stringify(a)===JSON.stringify(b)}
function tuningDraftKey(p){return tuningRuntimeKey(p?.yamlFileKey,p?.yamlPath)}
function renderTuningFields(){const x=selectedExperiment,fields=tuningFieldsFor(x),readOnly=obj('server').read_only===true,reset=$('resetExperimentYaml');rememberTuningBaseline(fields);setText('labYamlMode',readOnly?'LOCKED':'WRITE');if(reset){reset.hidden=!fields.some(p=>p.yamlFileKey&&baselineConfigValue(p.yamlFileKey,p.yamlPath)!==undefined);reset.disabled=readOnly||!!recordStartedMs}if(!fields.length){$('tuningFields').innerHTML='<div class="empty-state">Subbab ini adalah validasi/ringkasan; tidak ada parameter YAML aktif yang perlu dituning.</div>';return}let html='';fields.forEach((p,i)=>{const isYaml=!!p.yamlFileKey,ro=p.kind==='yaml_readonly'||p.locked||readOnly,dkey=isYaml?tuningDraftKey(p):'',val=isYaml?(tuningDrafts.has(dkey)?tuningDrafts.get(dkey):configValue(p.yamlFileKey,p.yamlPath)):(localRunValues[`${currentExp}:${x.id}:${p.key||p.label}`]??p.placeholder??''),base=isYaml?baselineConfigValue(p.yamlFileKey,p.yamlPath):undefined,changed=isYaml&&base!==undefined&&!tuningValueEqual(val,base),typ=p.kind==='bool'?'checkbox':p.kind==='int'||p.kind==='float'?'number':'text',step=p.kind==='int'?'1':'any',checked=typ==='checkbox'&&!!val;html+=`<div class="tuning-field ${ro?'readonly':''}"><div class="tuning-field-head"><label>${escapeHtml(p.label||p.key||'Parameter')}</label><span>${isYaml?escapeHtml(p.yamlFileKey):'RUN / GT'}${changed?' • MODIFIED':''}${ro?' • LOCKED':''}</span></div><div class="tuning-input-row">${typ==='checkbox'?`<label class="switch"><input id="tuneField-${i}" data-tune-index="${i}" type="checkbox" ${checked?'checked':''} ${ro?'disabled':''}><i></i><b>${checked?'TRUE':'FALSE'}</b></label>`:`<input id="tuneField-${i}" data-tune-index="${i}" type="${typ}" step="${step}" value="${escapeHtml(val??'')}" ${ro?'readonly':''}>`} ${ro?'':`<button class="param-save" data-field-index="${i}">${isYaml?'SAVE YAML':'SET'}</button>`}</div><code>${escapeHtml(p.yamlPath||p.key||'run identity')}</code>${base!==undefined?`<small>Baseline: <b>${escapeHtml(String(base))}</b>${changed?' • nilai YAML sedang diuji':''}</small>`:''}${runtimeTuningBadge(p)}${p.help?`<small>${escapeHtml(p.help)}</small>`:''}</div>`});$('tuningFields').innerHTML=html;qa('.param-save',$('tuningFields')).forEach(b=>b.onclick=()=>saveTuningField(+b.dataset.fieldIndex,false));qa('[data-tune-index]',$('tuningFields')).forEach(e=>{const captureDraft=()=>{const i=+e.dataset.tuneIndex,p=fields[i],ro=p?.kind==='yaml_readonly'||p?.locked||readOnly;if(p?.yamlFileKey&&!ro)tuningDrafts.set(tuningDraftKey(p),e.type==='checkbox'?e.checked:e.value)};e.oninput=captureDraft;e.onchange=()=>{captureDraft();if(e.type==='checkbox'){const b=q('b',e.parentElement);if(b)b.textContent=e.checked?'TRUE':'FALSE'}const i=+e.dataset.tuneIndex,p=fields[i],ro=p?.kind==='yaml_readonly'||p?.locked||readOnly;if(p?.yamlFileKey&&!ro&&currentExp!=='navigation')saveTuningField(i,true)}})}
async function writeTuningField(p,value,automatic=false){const key=tuningRuntimeKey(p.yamlFileKey,p.yamlPath),navGuard=currentExp==='navigation';if(navGuard&&tuningWriteInFlight.has(key)){toast('Parameter navigasi masih diproses • tunggu status APPLIED/NEXT_START',true);return false}if(navGuard)tuningWriteInFlight.add(key);try{const r=await fetch('/api/config/set',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file_key:p.yamlFileKey,path:p.yamlPath,value})}),j=await r.json(),ra=j.runtime_apply||{};runtimeTuningStatus.set(key,ra);const st=String(ra.state||'YAML_ONLY'),actual=ra.actual_value!=null?` • actual=${ra.actual_value}`:'';const success=r.ok&&(!ra.attempted||ra.verified===true||st==='NEXT_MAPPING'||st==='NEXT_START');const bad=!success||['VERIFY_FAILED','RELOAD_REQUIRED'].includes(st);if(success)tuningDrafts.delete(key);toast((automatic?'Auto-save: ':'')+(j.message||'YAML response')+` • Runtime=${st}${actual}`,bad);if(j.config?.files)configs=j.config.files;renderTuningFields();renderCalibration();renderTuning();return success}catch(e){toast('YAML save gagal: '+e.message,true);return false}finally{if(navGuard)tuningWriteInFlight.delete(key)}}
async function saveTuningField(i,automatic=false){const p=tuningFieldsFor(selectedExperiment)[i],el=$(`tuneField-${i}`);if(!p||!el)return;let value=p.kind==='bool'?el.checked:el.value;if(p.kind==='int')value=parseInt(value,10);if(p.kind==='float')value=parseFloat(value);if((p.kind==='int'||p.kind==='float')&&!Number.isFinite(value))return toast('Nilai numerik tidak valid',true);if(!p.yamlFileKey){const key=p.key||p.label;localRunValues[`${currentExp}:${selectedExperiment.id}:${key}`]=value;if(currentExp==='navigation'&&selectedExperiment.id==='4.2.5')persistBab425GroundTruth(key,value);toast(currentExp==='navigation'&&selectedExperiment.id==='4.2.5'?'Referensi fisik 4.2.5 disimpan dan dipakai untuk Map 1-3':'Nilai run/ground truth disimpan untuk sesi browser');if(currentExp==='navigation'&&selectedExperiment.id==='4.2.5'){renderExperimentTable();renderExperimentGraphs();renderSourceAudit()}return}return writeTuningField(p,value,automatic)}
async function resetSelectedExperimentYaml(){
  if(!selectedExperiment)return;
  if(recordStartedMs)return toast('Stop recording sebelum Reset Params',true);
  const fields=tuningFieldsFor(selectedExperiment),seen=new Set(),items=[];
  for(const p of fields){
    if(!p.yamlFileKey||!p.yamlPath)continue;
    const k=baselineKey(p.yamlFileKey,p.yamlPath),base=tuningBaseline.get(k);
    if(base===undefined||seen.has(k)||p.kind==='yaml_readonly'||p.locked)continue;
    seen.add(k);items.push({p,base});
  }
  if(!items.length)return toast('Subbab ini tidak memiliki parameter editable yang perlu di-reset',true);
  const domain=currentExp==='navigation'?'Navigation':currentExp==='perception'?'Perception':'ESC / FOC';
  confirmModal('Reset Params ke nilai awal',`${domain} ${selectedExperiment.id} • ${items.length} parameter akan dikembalikan ke nilai saat GUI pertama kali membacanya.`,async()=>{
    let okCount=0;
    for(const {p,base} of items){
      try{
        const r=await fetch('/api/config/set',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file_key:p.yamlFileKey,path:p.yamlPath,value:base})});
        const j=await r.json();
        if(!r.ok){toast(`Reset ${p.label} gagal: ${j.message||r.status}`,true);break}
        if(j.config?.files)configs=j.config.files;
        okCount++;
      }catch(e){toast(`Reset ${p.label} gagal: ${e.message}`,true);break}
    }
    renderTuningFields();renderCalibration();renderTuning();
    if(okCount===items.length)toast(`${okCount} parameter ${domain} kembali ke nilai awal`);
  });
}

