    if(id==='4.4.4'){if(selectedGraphIndex===0)return R({source:'condition',label:'Skenario lintasan'},[{label:'Success rate',path:'derived.nav_success_pct',stat:'last',unit:'%'},{label:'Navigation time',path:'goal_state.duration_s',stat:'last'}],['4.4.3']);return R({source:'condition',label:'Skenario lintasan'},[{label:'Endpoint error',path:'derived.endpoint_error_m',stat:'last'},{label:'Goal yaw error',path:'derived.goal_yaw_error_rad',stat:'last'}],['4.4.3']);}
