function metricUnit(path,label=''){const p=String(path||'').toLowerCase(),l=String(label||'').toLowerCase();if(p.includes('_pct')||p.includes('percent'))return '%';if(p.includes('rate_hz')||p.endsWith('.fps'))return 'Hz';if(p.includes('jitter_ms')||p.includes('latency_ms')||p.endsWith('_ms'))return 'ms';if(p.includes('alignment_lateral_error_cm')||l.includes('(cm)'))return 'cm';if(p.includes('yaw_deg')||l.includes('(deg)'))return 'deg';if(p.includes('yaw_rad')||p.includes('heading_error_rad')||p.endsWith('.yaw')||l.includes('(rad)'))return 'rad';if(p.includes('rpm'))return 'RPM';if(p.includes('vbus'))return 'V';if(/(^|\.)(ia|ib|iq|id)(_a)?$/.test(p)||p.endsWith('_a'))return 'A';if(/imu(?:_raw)?\.a[xyz]$/.test(p))return 'm/s²';if(/imu(?:_raw)?\.g[xyz]$/.test(p))return 'rad/s';if(p.includes('velocity')||p.endsWith('.v')||l==='vx')return 'm/s';if(p.includes('range')||p.includes('length_m')||p.includes('error_m')||p.endsWith('.x')||p.endsWith('.y'))return 'm';if(p.includes('encoder_count'))return 'count';if(p.includes('electrical_sector'))return 'sector';if(p.includes('count'))return 'count';if(p.includes('confidence')||p.includes('normalized'))return 'ratio';return 'value'}
function seriesBounds(series){const vals=series.flatMap(s=>s.data.map(p=>p.v)).filter(Number.isFinite);if(!vals.length)return[-1,1];let lo=Math.min(...vals),hi=Math.max(...vals);if(lo===hi){const e=Math.max(Math.abs(lo)*.1,.5);lo-=e;hi+=e}else{const d=hi-lo;lo-=d*.12;hi+=d*.12}return[lo,hi]}
