function metricStats(path){const a=metricHistory.get(path)||[];if(!a.length)return null;const v=a.map(p=>p.v),mean=v.reduce((x,y)=>x+y,0)/v.length,rmse=Math.sqrt(v.reduce((x,y)=>x+y*y,0)/v.length);return {first:v[0],last:v.at(-1),mean,rmse,min:Math.min(...v),max:Math.max(...v),std:Math.sqrt(v.reduce((x,y)=>x+(y-mean)**2,0)/v.length),positive_pct:100*v.filter(x=>x>0).length/v.length,count:v.length}}
