function perceptionSettlingSeconds(path,tolerance){const a=metricHistory.get(path)||[];if(a.length<2||!Number.isFinite(+tolerance))return undefined;for(let i=0;i<a.length;i++){if(a.slice(i).every(p=>Math.abs(+p.v)<=+tolerance))return Math.max(0,(a[i].s??i)-(a[0].s??0))}return undefined}
