function augmentPerceptionMetrics(metrics){if(currentExp!=='perception')return metrics;const latTolM=+(configValue('alignment','alignment.lateral_tolerance_m')??0.02),yawTol=+(configValue('alignment','alignment.yaw_tolerance_deg')??1),fwdTol=runFieldNumber('forward_tolerance_px');const ls=perceptionSettlingSeconds('derived.alignment_lateral_error_cm',latTolM*100),ys=perceptionSettlingSeconds('alignment_state.error_yaw_deg',yawTol),fs=perceptionSettlingSeconds('derived.forward_error_px',fwdTol);putMetricStat(metrics,'derived.perception_lateral_settling_s',ls);putMetricStat(metrics,'derived.perception_yaw_settling_s',ys);putMetricStat(metrics,'derived.perception_combined_settling_s',Number.isFinite(ls)&&Number.isFinite(ys)?Math.max(ls,ys):undefined);putMetricStat(metrics,'derived.perception_forward_settling_s',fs);putMetricStat(metrics,'derived.perception_lateral_overshoot_cm',perceptionOvershoot('derived.alignment_lateral_error_cm'));putMetricStat(metrics,'derived.perception_yaw_overshoot_deg',perceptionOvershoot('alignment_state.error_yaw_deg'));putMetricStat(metrics,'derived.perception_forward_overshoot_px',perceptionOvershoot('derived.forward_error_px'));putMetricStat(metrics,'derived.forward_stopping_error_cm',resolveMetricPath('derived.forward_stopping_error_cm'));return metrics}
function archiveCompletedRun(){if(!selectedExperiment)return;const metrics={};for(const [path,a] of metricHistory.entries()){if(!a?.length)continue;const st=metricStats(path);if(st)metrics[path]=st}if(!Object.keys(metrics).length)return null;augmentPerceptionMetrics(metrics);const entry={domain:currentExp,id:selectedExperiment.id,section:selectedExperiment.section||selectedExperiment.id,variation:$('runVariation')?.value||'',condition:$('runCondition')?.value||'',fields:currentFieldSnapshot(),metrics,at:new Date().toISOString()};runSummaryHistory.push(entry);while(runSummaryHistory.length>300)runSummaryHistory.shift();try{localStorage.setItem('adv-bab4-run-summaries-v2',JSON.stringify(runSummaryHistory))}catch(_){}return entry}
function runMetric(entry,path,stat='mean'){if(path.startsWith('derived.imu_yaw_')){const st=imuYawEntryStats(entry);if(path==='derived.imu_yaw_reference_deg')return st.ref;if(path==='derived.imu_yaw_mean_deg')return st.yawMean;if(path==='derived.imu_yaw_error_mean_deg')return st.errorMean;if(path==='derived.imu_yaw_mae_deg')return st.mae;if(path==='derived.imu_yaw_rmse_deg')return st.rmse;}if(path==='derived.lidar_reference_m'){const ref=Number(entry?.fields?.gt_distance_m);return Number.isFinite(ref)?ref:undefined}if(path==='derived.lidar_error_mean_m'){const ref=Number(entry?.fields?.gt_distance_m),mean=Number(entry?.metrics?.['lidar_raw.range_center_m']?.mean);return Number.isFinite(ref)&&Number.isFinite(mean)?mean-ref:undefined}const st=entry?.metrics?.[path];return st&&Number.isFinite(+st[stat])?+st[stat]:undefined}
function bab425SyntheticRuns(){const {name,physical}=bab425Reference();if(!Number.isFinite(physical))return [];const stat=v=>({first:v,last:v,mean:v,rmse:Math.abs(v),min:v,max:v,std:0,positive_pct:v>0?100:0,count:1});return [1,2,3].map(slot=>{const item=savedMapItem(slot),mapDim=mapStructureDimensionFor(item);if(item?.available!==true||!Number.isFinite(mapDim))return null;const err=Math.abs(mapDim-physical);return {domain:'navigation',id:'4.2.5',section:'4.2.5 Analisis Kualitas Struktur Map',variation:`Map ${slot}`,condition:'AUTO SAVED MAP',fields:{map_name:`Map ${slot}`,reference_name:name,reference_dimension_m:physical},metrics:{'derived.map_structure_error_m':stat(err),'derived.reference_dimension_m':stat(physical),'derived.map_dimension_m':stat(mapDim)},at:new Date(Number(item.modified_at_ms||Date.now())).toISOString(),synthetic:true}}).filter(Boolean)}
