async function deleteMappingSlot(){const slot=mappingRunSlot();if(!slot)return;const item=savedMapItem(slot);const exists=item?.available===true;const text=exists?`Hapus permanen hasil MAP ${slot} (PGM + YAML)? Map yang sedang ACTIVE di Nav2 atau sedang mapping akan ditolak oleh backend.`:`Map ${slot} belum memiliki PGM/YAML. Bersihkan slot ini?`;confirmModal(`DELETE MAP ${slot}`,text,async()=>{try{const r=await fetch('/api/mapping/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slot})}),j=await r.json();toast(j.message||`DELETE MAP ${slot}`,!r.ok);if(r.ok){await loadSavedMapCatalog(true);mappingPreviewImage=null;mappingPreviewAt=0;updateRunControlMode();updateNavMapSelectionUi();drawExperimentMap()}}catch(e){toast('DELETE MAP gagal: '+e.message,true)}})}
function updateRunControlMode(){const start=$('startCsvBtn'),stop=$('stopCsvBtn'),del=$('deleteMapBtn'),png=$('saveMapPngBtn');if(!start||!stop)return;const slot=mappingRunSlot();if(!slot){mappingUiActive=false;mappingRequestPending=false;mappingRequestStartedMs=0;start.textContent='● START CSV';stop.textContent='■ STOP & SAVE CSV';if(del)del.hidden=true;if(png)png.hidden=true;return}if(del){del.hidden=false;del.textContent=`DELETE MAP ${slot}`;}if(png){png.hidden=false;png.textContent=`⇩ SAVE PNG MAP ${slot}`;}const ms=obj('mapping_status'),active=ms.active===true,activeSlot=Number(ms.slot||0),phase=String(ms.phase||'READY').toUpperCase();if(active||phase==='ERROR'){mappingRequestPending=false;mappingRequestStartedMs=0}const serverPreparing=!active&&activeSlot===slot&&(phase==='PREPARING'||phase==='STARTING'||phase==='ENGINE_PREPARING'),pending=mappingRequestPending||serverPreparing,busy=active||pending;if(png){const item=savedMapItem(slot);png.disabled=busy||item?.available!==true;png.title=item?.available===true?`Download hasil MAP ${slot} sebagai PNG`:`STOP + SAVE PGM MAP ${slot} terlebih dahulu`; }if(active&&!mappingUiActive){mappingPreviewImage=null;mappingPreviewAt=0;recordStartedMs=Date.now();chartEpochMs=recordStartedMs;lastLabSecond=-1;metricHistory.clear();scatterHistory.clear();tableRunRows.clear();captureLabTelemetry()}else if(!active&&mappingUiActive){recordStartedMs=0;lastLabSecond=-1}mappingUiActive=active;start.textContent=pending?`… STARTING MAP ${slot}`:(ms.engine_ready===true?`▶ START MAPPING ${slot}`:`◌ ENGINE PREPARING`);stop.textContent=`■ STOP + SAVE PGM ${slot}`;start.disabled=busy;stop.disabled=!(active&&activeSlot===slot);if(del){const ns=obj('nav_map_switch_status'),inUse=Number(ns.active_slot||0)===slot&&(ns.nav_enabled===true||ns.busy===true);del.disabled=busy||inUse;del.title=inUse?'STOP Navigation atau pindahkan map sebelum DELETE':'Hapus PGM + YAML + data struktur map ini';}setText('labRecorderState',active?`MAPPING ${activeSlot}`:pending?`STARTING MAP ${slot}`:(ms.engine_ready===true?'ENGINE READY':'ENGINE PREPARING'));setText('recordChip',active?phase:pending?'PREPARING':(ms.engine_ready===true?'ENGINE READY':'ENGINE PREPARING'));$('recordChip').className='status-chip '+(active?'recording':'waiting');if(active){setText('recordElapsed',`MAP ${activeSlot} • ${phase}`);setText('recordPath',ms.map_fresh?'Live SLAM /map: FRESH':'Live SLAM /map: WAIT');setText('labRecorderSamples','1 sample/s • mapping live')}else if(pending){setText('recordElapsed',`MAP ${slot} • PREPARING`);setText('recordPath','Map kosong • menyiapkan SLAM');setText('labRecorderSamples','menunggu /map baru')}else{setText('recordElapsed','0 s');setText('recordPath',`Output setelah STOP + SAVE: map_${slot}.pgm`);setText('labRecorderSamples',Number(ms.saved_slot||0)===slot&&ms.saved_pgm?'PGM saved':'mapping belum dimulai')}if(ms.error)setText('recordMessage','Mapping: '+ms.error);else if(!active&&!pending)setText('recordMessage',`BAB 4.2.${slot} • ${ms.engine_ready===true?'standby engine siap':'standby engine dipanaskan'} • parameter 4.2.1-4.2.3 memakai runtime YAML yang sama`)}
$('startCsvBtn').onclick=startRunControl;$('stopCsvBtn').onclick=stopRunControl;$('saveMapPngBtn').onclick=saveMappingPng;$('resetNavResultsBtn').onclick=resetNavigationResults;$('deleteMapBtn').onclick=deleteMappingSlot;$('resetExperimentYaml').onclick=resetSelectedExperimentYaml;$('refreshExperimentConfig').onclick=async()=>{await loadConfig();renderTuningFields();toast('YAML dimuat ulang dari source')};$('experimentSearch').oninput=renderExperimentList;$('graphClearBtn').onclick=()=>{metricHistory.clear();scatterHistory.clear();trajectoryHistory.length=0;trajectoryPlanHistory.length=0;chartEpochMs=Date.now();lastLabSecond=-1;renderExperimentGraphs()};
