function renderLabWorkbench(){if(!selectedExperiment)return;const pageActive=!!q('#page-experiments.active'),backgroundCapture=!!recordStartedMs||obj('mapping_status').active===true||loopClosureSession.active;if(!pageActive&&!backgroundCapture)return;syncLoopClosureSession();captureLabTelemetry();if(!pageActive)return;const now=Date.now();if(now-lastExperimentPanelRefreshMs<750)return;updateRunControlMode();updateNavigationResetButton();renderContextVisual();refreshExperimentLivePanels(true)}
